mapper.sql:
FROM shop s JOIN shop_type t ON t.id=s.type_id JOIN shop_type root ON root.id=t.parent_id
    WHERE s.status='ACTIVE' AND s.city_code=#{q.cityCode} AND root.id=#{q.categoryId}
    AND t.id=#{q.typeId}
    AND (s.name LIKE CONCAT('%',#{q.keyword},'%') OR EXISTS
      (SELECT 1 FROM voucher_product vp WHERE vp.shop_id=s.id AND  AND ))
